def editDistanceAtMostK(s, t, k):
    m, n = len(s), len(t)
    if abs(m - n) > k:
        return -1
    INF = k + 1
    w = 2 * k + 1
    prev = [INF] * (w + 1)
    for j in range(0, min(n, k) + 1):
        prev[j + k] = j
    for i in range(1, m + 1):
        cur = [INF] * (w + 1)
        a = s[i - 1]
        for d in range(w):
            j = i + d - k
            if j < 0 or j > n:
                continue
            if j == 0:
                v = i
            else:
                v = prev[d] + (0 if a == t[j - 1] else 1)
                u = prev[d + 1] + 1
                if u < v:
                    v = u
                if d > 0:
                    u = cur[d - 1] + 1
                    if u < v:
                        v = u
            cur[d] = v if v < INF else INF
        prev = cur
    ans = prev[n - m + k]
    return ans if ans <= k else -1
